  else if (m < 60) s = `${m} minute${m === 1 ? "" : "s"}`;
  else if (h < 24) s = `${h} hour${h === 1 ? "" : "s"}`;
  else if (d < 30) s = `${d} day${d === 1 ? "" : "s"}`;
  else if (d < 365) {
    const mo = Math.round(d / 30);
    s = `${mo} month${mo === 1 ? "" : "s"}`;
  } else {
    const y = Math.round(d / 365);
    s = `${y} year${y === 1 ? "" : "s"}`;
  }
