function parseAgo(s: string) {
  let ms = 0;
  for (const [, n, unit] of s.matchAll(/(\d+)\s*([mhd])/g)) {
    const v = Number(n);
    ms += unit === "m" ? v * 60_000 : unit === "h" ? v * 3_600_000 : v * 86_400_000;
  }
  return ms;
}

