+
+export type MailState = MailData & MailActions;
+
+const SEED_VERSION = 3;
+
+function freshData(): Omit<MailData, "settings"> {
+  const now = Date.now();
+  const seed = buildSeed(now);
+  return {
+    version: SEED_VERSION,
+    seededAt: now,
+    threads: seed.threads,
+    messages: seed.messages,
+    labels: SEED_LABELS,
