+      tick: (now) => {
+        let s: MailData = get();
+        const delivered: Delivered[] = [];
+        let changed = false;
+
+        const due = Object.values(s.threads).filter((t) => t.snoozedUntil && t.snoozedUntil <= now);
+        if (due.length) {
