  primary: { name: "Primary", icon: "inbox", color: "#0b57d0" },
  promotions: { name: "Promotions", icon: "sell", color: "#188038" },
  social: { name: "Social", icon: "group", color: "#1a73e8" },
  updates: { name: "Updates", icon: "info", color: "#e37400" },
