+}
+
+export interface ViewResult {
+  threads: Thread[];
+  folder?: FolderId;
+  query?: Query;
+}
+
+export function viewThreads(
+  view: View,
+  threads: Record<string, Thread>,
+  messages: Messages,
+  labels: Label[],
+  now: number,
+): ViewResult {
+  const all = Object.values(threads);
