+
+export const FOLDER_META: Record<FolderId, { name: string; icon: string }> = {
+  inbox: { name: "Inbox", icon: "inbox" },
+  starred: { name: "Starred", icon: "star" },
+  snoozed: { name: "Snoozed", icon: "schedule" },
