+    if (done && useUI.getState().toast?.message !== "Sending...") return;
+    ui().showToast(
+      {
+        message: "Message sent.",
+        action: { label: "Undo", run: undo },
+        secondary: { label: "View message", run: view },
+        duration: Math.max(4000, seconds * 1000),
+      },
+      undo,
+    );
