import { create } from "zustand";
import type { Attachment, Contact } from "./types";
import { uid } from "./utils";

export type ComposeMode = "new" | "reply" | "replyAll" | "forward";

export interface ComposeState {
  key: string;
  messageId?: string;
  threadId?: string;
  mode: ComposeMode;
