      disabled={disabled}
      onClick={onClick}
      className={cn(
        "flex h-9 w-full items-center gap-3 whitespace-nowrap px-4 text-left text-sm hover:bg-hover focus:bg-hover focus:outline-none disabled:opacity-40",
