          className="-mr-1 ml-0.5 inline-flex h-4 w-4 items-center justify-center rounded-sm opacity-70 hover:bg-black/10 hover:opacity-100"
        >
          <Icon name="close" size={13} />
        </button>
      )}
    </span>
  );
}

export function Modal({
  children,
  onClose,
  className,
  labelledBy,
}: {
  children: ReactNode;
  onClose: () => void;
  className?: string;
  labelledBy?: string;
}) {
  useEffect(() => {
    const key = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.stopPropagation();
        onClose();
      }
    };
    document.addEventListener("keydown", key, true);
    return () => document.removeEventListener("keydown", key, true);
  }, [onClose]);
  return createPortal(
    <div className="animate-fade fixed inset-0 z-[800] flex items-center justify-center bg-black/40 p-4" onPointerDown={(e) => e.target === e.currentTarget && onClose()}>
      <div role="dialog" aria-modal aria-labelledby={labelledBy} className={cn("animate-pop max-h-full overflow-auto rounded-2xl bg-raised text-fg shadow-compose", className)}>
        {children}
      </div>
    </div>,
