            setValue(q);
            onClose?.();
            runSearch(q);
          }}
        />
      </Popover>
    </div>
  );
}

function Highlight({ text, term }: { text: string; term: string }) {
  if (!term || term.includes(":")) return <>{text}</>;
  const i = text.toLowerCase().indexOf(term);
  if (i < 0) return <>{text}</>;
  return (
    <>
      {text.slice(0, i)}
      <b>{text.slice(i, i + term.length)}</b>
      {text.slice(i + term.length)}
