          onMouseDown={(e) => e.preventDefault()}
        >
          <div className="mx-4 h-px bg-line" />
          {!term && (
            <div className="flex flex-wrap gap-2 px-4 py-3">
              {[
                ["attach_file", "Has attachment", "has:attachment"],
                ["mark_email_unread", "Unread", "is:unread"],
