                  confirmLabel: "Delete",
                  danger: true,
                  onConfirm: () => {
                    deleteLabel(label.id);
                    if (active) navigate("#inbox");
                    showToast({ message: `Label "${label.name}" deleted.` });
                  },
                });
              }}
            />
          </Popover>
        </>
      }
    />
  );
