              onClick={() => {
                menu.close();
                navigate(`#search/${encodeURIComponent(`label:${label.name.toLowerCase().replace(/\s+/g, "-")}`)}`);
              }}
            />
            <MenuItem
              icon="delete"
              label="Remove label"
              onClick={() => {
                menu.close();
                openDialog({
                  type: "confirm",
                  title: "Remove label",
