        <ul>
          {labels.map((l) => (
            <LabelItem
              key={l.id}
              label={l}
              count={counts.labels[l.id] ?? 0}
              active={isActive({ kind: "label", id: l.id })}
              collapsed={collapsed}
              currentLabel={currentLabel}
            />
          ))}
        </ul>
      </nav>
    </div>
  );
}

function NavItem({
  icon,
  label,
  count,
  strongCount,
  view,
  active,
  collapsed,
  drop,
  currentLabel,
  iconColor,
  trailing,
}: {
  icon: string;
  label: string;
  count: number;
  strongCount?: boolean;
  view: View;
  active: boolean;
  collapsed: boolean;
  drop?: DropTarget;
  currentLabel?: string;
