        onDragOver={(e) => {
          if (!droppable || !hasThreadData(e)) return;
          e.preventDefault();
          e.dataTransfer.dropEffect = "move";
          setOver(true);
        }}
        onDragLeave={() => setOver(false)}
        onDrop={(e) => {
          setOver(false);
          if (!droppable) return;
          e.preventDefault();
          dropOn(drop!, readThreadData(e), currentLabel);
