        {!collapsed && <span className="min-w-0 flex-1 truncate">{label}</span>}
        {!collapsed && count > 0 && (
          <span className={cn("text-xs group-hover/nav:opacity-0", strongCount || active ? "font-bold" : "font-medium", trailing && "group-hover/nav:invisible")}>
