+        </form>
+      </Popover>
+    </>
+  );
+}
+
+const EMOJI = "😀 😂 🥲 😊 😍 🤔 😎 🙃 😅 😴 🥳 🤯 👍 👎 👏 🙌 🙏 💪 👋 🤝 ❤️ 💜 🔥 ✨ 🎉 🎂 ☕ 🍕 🥟 🌮 🚀 ✅ ❌ ⚠️ 📎 📅 📌 💡 📈 🧗 🐕 🌊 ✈️ 🏖️ 🎧 📚".split(" ");
+
+function EmojiButton({ editorRef, onChange }: { editorRef: React.RefObject<HTMLDivElement | null>; onChange: () => void }) {
+  const menu = useMenu();
+  const sel = useSavedSelection(editorRef);
