+        <div className="grid grid-cols-8 gap-0.5">
+          {EMOJI.map((e) => (
+            <button
+              key={e}
+              type="button"
+              onMouseDown={(ev) => ev.preventDefault()}
+              onClick={() => {
+                sel.restore();
+                document.execCommand("insertText", false, e);
+                sel.save();
+                onChange();
+              }}
+              className="flex h-9 w-9 items-center justify-center rounded-lg text-xl hover:bg-hover"
+            >
+              {e}
+            </button>
+          ))}
+        </div>
+      </Popover>
