+        "fixed bottom-5 right-4 z-[500] flex h-14 items-center gap-3 rounded-2xl bg-compose pl-4 text-on-compose shadow-[0_1px_3px_rgba(0,0,0,.3),0_4px_8px_3px_rgba(0,0,0,.15)] transition-[width,padding] duration-200",
