      <pre className="min-h-0 flex-1 overflow-auto whitespace-pre-wrap break-all px-6 py-4 font-mono text-xs text-fg-2">{raw}</pre>
    </Modal>
  );
}

const SHORTCUTS: [string, [string, string][]][] = [
