    await p.locator('nav a[href="#inbox"]').click();
    await p.getByRole("tab", { name: /Promotions/ }).click();
    await p.waitForTimeout(250);
    expect(p.url().includes("#category/promotions"), p.url());
    await shot(p, "13-promotions");
