            onConfirm: () => {
              useMail.getState().deleteDraft(m.id);
              useUI.getState().showToast({ message: "Draft discarded." });
            },
          })
        }
      />
    </div>
  );
}

function ThreadMoreMenu({ thread, last, onLeave }: { thread: Thread; last?: Message; onLeave: () => void }) {
