  const c = ui().composes.find((x) => x.key === key);
  if (!c) return undefined;
  if (!c.messageId && !composeHasContent(c)) return undefined;
  const r = mail().saveDraft({
    messageId: c.messageId,
    threadId: c.threadId,
    to: c.to,
    cc: c.cc,
    bcc: c.bcc,
