              </button>
            ))}
          </div>
        )}
        {top && <MobileCompose key={top.key} compose={top} />}
      </>
    );
  }

  return (
    <div className="pointer-events-none fixed bottom-0 right-4 z-[600] flex flex-row-reverse items-end gap-4">
      {floating.map((c) => (
        <ComposeWindow key={c.key} compose={c} />
      ))}
    </div>
  );
}

