  const att = attachments[i];
  useEffect(() => {
    const key = (e: KeyboardEvent) => {
      if (e.key === "Escape") close();
      if (e.key === "ArrowRight") setI((x) => Math.min(x + 1, attachments.length - 1));
      if (e.key === "ArrowLeft") setI((x) => Math.max(x - 1, 0));
