    document.addEventListener("keydown", key, true);
    return () => document.removeEventListener("keydown", key, true);
  }, [attachments.length, close]);
  if (!att) return null;
  const kind = attachmentKind(att.name, att.mime);
  const meta = KIND_META[kind];

  return createPortal(
    <div className="animate-fade fixed inset-0 z-[850] flex flex-col bg-[#202124]/95 text-white" role="dialog" aria-modal aria-label={`Preview of ${att.name}`}>
      <div className="flex h-16 shrink-0 items-center gap-3 px-3">
