              props.onSelect(t, e);
            }}
            className="relative mt-0.5 h-10 w-10 shrink-0"
          >
            {selected ? (
              <span className="flex h-10 w-10 items-center justify-center rounded-full bg-accent text-on-primary">
                <Icon name="check" size={22} />
              </span>
