                </div>
                <div className="truncate text-sm text-fg-3">{highlight(snip, terms)}</div>
              </div>
              <StarButton starred={t.starred} onToggle={() => act.toggleStar([t.id])} className="-mr-1.5 -mt-2 h-9" />
