  await tryStep("bottom reading pane", async () => {
    await p.evaluate(() => {
      const s = JSON.parse(localStorage.getItem("mail-store"));
      s.state.settings.readingPane = "bottom";
      localStorage.setItem("mail-store", JSON.stringify(s));
