  return (
    <div className="mx-3 mb-1 flex flex-wrap items-center gap-0.5 rounded-lg px-1 py-0.5 shadow-[0_1px_3px_rgba(0,0,0,.2)]">
      {b("undo", "Undo", "undo")}
      {b("redo", "Redo", "redo")}
      <span className="mx-1 h-5 w-px bg-line" />
      <button ref={fontMenu.ref} type="button" {...keep} onClick={fontMenu.toggle} className="flex h-8 items-center gap-0.5 rounded px-2 text-sm text-fg-2 hover:bg-hover" data-tip="Font">
