import { chromium } from "playwright";

const browser = await chromium.launch({ channel: "chrome", headless: true });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const p = await ctx.newPage();
p.on("console", (m) => console.log("console:", m.type(), m.text()));
await p.goto("http://localhost:9349/");
await p.waitForSelector("[data-thread]");
await p.locator("main [data-thread]", { hasText: "Photos from the lake house" }).first().getByText("Photos from the lake house").click();
await p.waitForSelector("article");
await p.locator('main [role="button"]', { hasText: "Ethan Chen" }).first().click();
await p.waitForTimeout(300);
await p.locator("[data-attachment]").first().click();
await p.waitForTimeout(1200);
const info = await p.evaluate(() => {
  const d = document.querySelector('[aria-label^="Preview of"]');
  if (!d) return "no dialog";
  const img = d.querySelector("img");
  const cs = getComputedStyle(d);
  return {
    bg: cs.backgroundColor,
    opacity: cs.opacity,
    img: img ? { w: img.naturalWidth, h: img.naturalHeight, cw: img.clientWidth, ch: img.clientHeight, src: img.src.slice(0, 80), complete: img.complete } : null,
    html: d.innerHTML.slice(0, 400),
  };
});
console.log(JSON.stringify(info, null, 2));
await p.screenshot({ path: new URL("../.shots/dbg-viewer.png", import.meta.url).pathname });
await browser.close();

