import { chromium } from "playwright";

const OUT = new URL("../.shots/", import.meta.url).pathname;
const browser = await chromium.launch({ channel: "chrome", headless: true });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const p = await ctx.newPage();
p.on("pageerror", (e) => console.log("PAGEERROR", e.message));
await p.goto("http://localhost:9349/");
await p.waitForSelector("[data-thread]");

async function open(subject) {
  await p.evaluate(() => (location.hash = "#inbox"));
  await p.waitForTimeout(200);
  await p.locator("main [data-thread]", { hasText: subject }).first().getByText(subject).first().click();
  await p.waitForSelector("article");
  await p.waitForTimeout(200);
}

await open("Photos from the lake house");
await p.locator('main [role="button"]', { hasText: "Ethan Chen" }).first().click();
await p.waitForTimeout(200);
await p.locator("[data-attachment]").first().click();
await p.waitForTimeout(500);
await p.screenshot({ path: `${OUT}70-viewer-image.png` });
await p.keyboard.press("Escape");

await open("Illustrations for the help center");
const cards = p.locator("[data-attachment]");
const n = await cards.count();
for (let i = 0; i < n; i++) {
  await cards.nth(i).click();
  await p.waitForTimeout(500);
  await p.screenshot({ path: `${OUT}71-viewer-${i}.png` });
  await p.keyboard.press("Escape");
  await p.waitForTimeout(200);
}

await open("Atlas launch");
await p.locator('main [role="button"]', { hasText: "Maya Patel" }).first().click();
await p.waitForTimeout(200);
await p.locator("[data-attachment]").first().click();
await p.waitForTimeout(500);
await p.screenshot({ path: `${OUT}72-viewer-pdf.png` });
await browser.close();
console.log("done", n);

