      </div>
    );
  }
  if (kind === "calendar") return <CalendarPreview att={att} />;
  return (
    <div className="max-h-[calc(100dvh-180px)] w-[min(680px,92vw)] overflow-y-auto rounded-sm bg-white px-[8%] py-[7%] text-[#202124] shadow-2xl">
