            </li>
          ))}
        </ul>
      </div>
    );
  }
  if (kind === "sheet") {
    const r = seededRandom(att.name);
    const cols = ["Week", "Users", "W1", "W2", "W4", "W8"];
    return (
      <div className="max-h-[calc(100dvh-180px)] w-[min(720px,92vw)] overflow-auto rounded bg-white text-[#202124] shadow-2xl">
