export interface Query {
  raw: string;
  text: string[];
  exclude: string[];
  from: string[];
  to: string[];
  subject: string[];
  label: string[];
  in?: string;
  is: string[];
  has: string[];
  filename: string[];
  category?: string;
  before?: number;
  after?: number;
  larger?: number;
}

function parseDate(v: string) {
  const m = v.match(/^(\d{4})[/-](\d{1,2})[/-](\d{1,2})$/);
  if (!m) return undefined;
  return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime();
}

function parseRelative(v: string, now: number) {
  const m = v.match(/^(\d+)([dwmy])$/);
  if (!m) return undefined;
  const n = Number(m[1]);
  const days = m[2] === "d" ? n : m[2] === "w" ? n * 7 : m[2] === "m" ? n * 30 : n * 365;
  return now - days * 86_400_000;
}

function parseSize(v: string) {
  const m = v.match(/^(\d+(?:\.\d+)?)([kmg]?)b?$/i);
  if (!m) return undefined;
  const mult = { "": 1, k: 1024, m: 1024 ** 2, g: 1024 ** 3 }[m[2].toLowerCase() as "" | "k" | "m" | "g"];
  return Number(m[1]) * mult;
}

export function parseQuery(raw: string, now = Date.now()): Query {
  const q: Query = { raw, text: [], exclude: [], from: [], to: [], subject: [], label: [], is: [], has: [], filename: [] };
  const re = /(-?)([a-z_]+):("[^"]*"|\S+)|(-?)"([^"]*)"|(-?)(\S+)/gi;
  for (const m of raw.matchAll(re)) {
    if (m[2]) {
      const key = m[2].toLowerCase();
      const value = m[3].replace(/^"|"$/g, "").toLowerCase();
      const neg = m[1] === "-";
      switch (key) {
        case "from":
          q.from.push(value);
          break;
        case "to":
        case "cc":
          q.to.push(value);
          break;
        case "subject":
          q.subject.push(value);
          break;
        case "label":
          q.label.push(value);
          break;
        case "in":
          q.in = value;
          break;
        case "is":
          q.is.push(neg ? `-${value}` : value);
          break;
        case "has":
          q.has.push(neg ? `-${value}` : value);
          break;
        case "filename":
          q.filename.push(value);
          break;
        case "category":
          q.category = value;
          break;
        case "before":
        case "older":
          q.before = parseDate(value);
          break;
        case "after":
        case "newer":
          q.after = parseDate(value);
          break;
        case "older_than":
          q.before = parseRelative(value, now);
          break;
        case "newer_than":
          q.after = parseRelative(value, now);
          break;
        case "larger":
          q.larger = parseSize(value);
          break;
        default:
          (neg ? q.exclude : q.text).push(`${key}:${value}`);
      }
    } else if (m[5] !== undefined) {
      (m[4] === "-" ? q.exclude : q.text).push(m[5].toLowerCase());
    } else if (m[7]) {
      (m[6] === "-" ? q.exclude : q.text).push(m[7].toLowerCase());
    }
  }
  return q;
}

export function queryTerms(q: Query) {
  return [...q.text, ...q.subject].filter((t) => t.length > 1);
}

export interface AdvancedFields {
  from: string;
  to: string;
  subject: string;
  hasWords: string;
  notWords: string;
  within: string;
  in: string;
  hasAttachment: boolean;
  unread: boolean;
}

const quote = (s: string) => (/\s/.test(s) ? `"${s}"` : s);

export function buildQuery(f: AdvancedFields) {
  const parts: string[] = [];
  if (f.from.trim()) parts.push(`from:${quote(f.from.trim())}`);
  if (f.to.trim()) parts.push(`to:${quote(f.to.trim())}`);
  if (f.subject.trim()) parts.push(`subject:${quote(f.subject.trim())}`);
  if (f.hasWords.trim()) parts.push(f.hasWords.trim());
  f.notWords

  }
  if (folder === "scheduled") return Math.min(...pool.map((m) => m.scheduledAt ?? m.date));
  return Math.max(0, ...pool.map((m) => m.date));
}

export function matchesQuery(t: Thread, messages: Messages, q: Query, labels: Label[], now: number) {
  const ms = threadMessages(t, messages);
  if (!q.in || !["trash", "spam", "anywhere"].includes(q.in)) {
    if (t.trashed || t.spam) return false;
  }
  if (q.in && q.in !== "anywhere" && q.in !== "all") {
    const map: Record<string, FolderId> = {
      inbox: "inbox",
      sent: "sent",
      drafts: "drafts",
      draft: "drafts",
      trash: "trash",
      spam: "spam",
      starred: "starred",
      snoozed: "snoozed",
      scheduled: "scheduled",
      important: "important",
    };
    const f = map[q.in];
    if (f && !inFolder(t, f, messages, now)) return false;
  }
  for (const is of q.is) {
    const neg = is.startsWith("-");
    const key = neg ? is.slice(1) : is;
    let v: boolean;
    if (key === "unread") v = isUnread(t, messages);
    else if (key === "read") v = !isUnread(t, messages);
    else if (key === "starred") v = t.starred;
    else if (key === "important") v = t.important;
    else if (key === "snoozed") v = isSnoozed(t, now);
    else if (key === "muted") v = !!t.muted;
    else continue;
    if (v === neg) return false;
  }
  for (const has of q.has) {
    const neg = has.startsWith("-");
    const key = neg ? has.slice(1) : has;
    let v: boolean;
    if (key === "attachment") v = hasAttachments(t, messages);
    else if (key === "userlabels") v = t.labels.length > 0;
    else if (key === "nouserlabels") v = t.labels.length === 0;
    else if (key === "star" || key === "yellow-star") v = t.starred;
    else continue;
    if (v === neg) return false;
  }
  if (q.category && t.category !== q.category) return false;
