  p.on("console", (m) => m.type() === "error" && errors.push(`[${name}] ${m.text()}`));
  p.on("pageerror", (e) => errors.push(`[${name}] PAGEERROR ${e.message}`));
  await p.goto(BASE);
  await p.waitForSelector("[data-thread]");
